var YT_CHANNEL_ID = 'UCZgpumlYClYA-rfrKp5QS6g';
var YT_CHANNEL_URL = 'https://www.youtube.com/@Attornialex';
var YT_RSS_PROXY = '';
async function fetchChannelVideos(){
  var rss = 'https://www.youtube.com/feeds/videos.xml?channel_id=' + YT_CHANNEL_ID;
  var url = YT_RSS_PROXY ? YT_RSS_PROXY + encodeURIComponent(rss) : rss;
  var resp = await fetch(url);
  if(!resp.ok) throw new Error('RSS no disponible');
  var doc = new DOMParser().parseFromString(await resp.text(), 'text/xml');
  var entries = [].slice.call(doc.querySelectorAll('entry'));
  if(!entries.length) throw new Error('Sin entradas');
  return entries.slice(0, 7).map(function(e){
    var id = (e.querySelector('videoId')||{}).textContent || '';
    return {
      id: id,
      title: (e.querySelector('title')||{}).textContent || '',
      desc: (e.querySelector('group description')||{}).textContent || '',
      tag: (e.querySelector('group category[label]')||{}).getAttribute ? e.querySelector('group category[label]').getAttribute('label') || '' : '',
      featured: false
    };
  });
}

